use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn generate_lookup_code (lookup : & SignatureLookup , output_file : & str) -> Result < () > { let mut code = String :: new () ; code . push_str ("// Generated signature lookup code\n") ; code . push_str ("// Use this for fast signature decoding\n\n") ; code . push_str ("use std::collections::HashMap;\n\n") ; code . push_str ("pub fn create_prime_lookup() -> HashMap<u64, Vec<String>> {\n") ; code . push_str ("    let mut map = HashMap::new();\n") ; for (prime , signature) in & lookup . prime_to_signature { if let Some (bindings) = lookup . signature_to_bindings . get (signature) { code . push_str (& format ! ("    map.insert({}, vec![{}]);\n" , prime , bindings . iter () . map (| b | format ! ("\"{}\"" , b)) . collect ::< Vec < _ >> () . join (", "))) ; } } code . push_str ("    map\n") ; code . push_str ("}\n\n") ; code . push_str ("pub fn create_emoji_lookup() -> HashMap<String, Vec<String>> {\n") ; code . push_str ("    let mut map = HashMap::new();\n") ; for (emoji , signature) in & lookup . emoji_to_signature { if let Some (bindings) = lookup . signature_to_bindings . get (signature) { code . push_str (& format ! ("    map.insert(\"{}\".to_string(), vec![{}]);\n" , emoji , bindings . iter () . map (| b | format ! ("\"{}\"" , b)) . collect ::< Vec < _ >> () . join (", "))) ; } } code . push_str ("    map\n") ; code . push_str ("}\n") ; fs :: write (output_file , code) ? ; println ! ("🔍 Lookup code written to {}" , output_file) ; Ok (()) }